ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from InventoryLib
---
if (isEmpty(payload))
    null
else do {
    var row = payload[0]
    var total = calculateTotal(row.warehouse_stock, row.regional_stock)
    ---
    {
        itemId: row.item_id,
        totalInventory: total,
        status: calculateStatus(total),
        reorderQuantity: calculateReorder(total),
        region: row.region
    }
}

db:update.db:input-parameters:
#[%dw 2.0
output application/java
import * from InventoryLib
var total = calculateTotal(vars.syncRow.warehouse_stock, vars.syncRow.regional_stock)
---
{
    itemId: vars.syncRow.item_id,
    totalInventory: total,
    status: calculateStatus(total)
}]
